//! A network of processes on localhost: four `sion node` processes and a
//! `sion gateway`, talking QUIC with post-quantum TLS and pinned keys.
//!
//! Every validator's keys are generated by `sion keys validator`, collected
//! by `sion genesis`; transfers go in through the gateway and come out
//! certified, ordered and executed on every node; a light client checks a
//! certified Pulse against the pinned chain identity; keys nobody pinned
//! and classical key exchange are refused; and a validator does not start
//! again in a consensus session it has signed in.
//!
//! The network test runs five processes with post-quantum signatures and
//! takes about 40 s on two cores: under a minute, so it is part of the fast
//! suite.

use std::fs::File;
use std::net::{SocketAddr, TcpListener, UdpSocket};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Output};
use std::time::{Duration, Instant};

use sion_cli::{HttpLedger, LedgerExt, Session};
use sion_core::ids::{AssetId, Pulse};
use sion_core::Amount;
use sion_net::{probe, KeyExchange, NetworkKey, Peer};
use sion_node::network::{
    load_network_key, read_json, NetworkGenesis, NodeEntry, NETWORK_KEY_FILE,
};

const SION: &str = env!("CARGO_BIN_EXE_sion");

/// The processes of one test network, killed when it goes out of scope.
struct Network {
    dir: PathBuf,
    children: Vec<(String, Child)>,
}

impl Network {
    fn new(name: &str) -> Network {
        let dir = std::env::temp_dir().join(format!("sion-net-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("home")).unwrap();
        Network {
            dir,
            children: Vec::new(),
        }
    }

    fn path(&self, name: &str) -> PathBuf {
        self.dir.join(name)
    }

    fn command(&self, args: &[String]) -> Command {
        let mut command = Command::new(SION);
        command.args(args).env("SION_HOME", self.path("home"));
        command
    }

    /// Runs `sion` to completion.
    fn run(&self, args: &[String]) -> Output {
        self.command(args).output().unwrap()
    }

    /// Runs `sion` to completion, which must succeed; returns its output.
    fn sion(&self, args: &[String]) -> String {
        let output = self.run(args);
        if !output.status.success() {
            self.fail(&format!(
                "sion {} failed:\n{}{}",
                args.join(" "),
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            ));
        }
        String::from_utf8_lossy(&output.stdout).into_owned()
    }

    /// Starts a long-running `sion` process logging to `<name>.log`.
    fn spawn(&mut self, name: &str, args: &[String]) {
        let log = File::create(self.path(&format!("{name}.log"))).unwrap();
        let child = self
            .command(args)
            .stdout(log.try_clone().unwrap())
            .stderr(log)
            .spawn()
            .unwrap();
        self.children.push((name.to_string(), child));
    }

    /// Stops process `name` abruptly.
    fn kill(&mut self, name: &str) {
        if let Some(index) = self.children.iter().position(|(n, _)| n == name) {
            let (_, mut child) = self.children.remove(index);
            let _ = child.kill();
            let _ = child.wait();
        }
    }

    /// Fails the test, showing the end of every process's log.
    fn fail(&self, message: &str) -> ! {
        for (name, _) in &self.children {
            let log =
                std::fs::read_to_string(self.path(&format!("{name}.log"))).unwrap_or_default();
            let lines: Vec<&str> = log.lines().collect();
            let tail = lines[lines.len().saturating_sub(15)..].join("\n");
            eprintln!("--- {name}.log ---\n{tail}");
        }
        panic!("{message}");
    }

    fn wait_until(&self, what: &str, timeout: Duration, mut done: impl FnMut() -> bool) {
        let deadline = Instant::now() + timeout;
        while !done() {
            if Instant::now() > deadline {
                self.fail(&format!("timed out after {timeout:?} waiting until {what}"));
            }
            std::thread::sleep(Duration::from_millis(200));
        }
    }
}

impl Drop for Network {
    fn drop(&mut self) {
        for (_, child) in &mut self.children {
            let _ = child.kill();
            let _ = child.wait();
        }
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

/// Free ports on the loopback interface: `udp` for QUIC, `tcp` for APIs.
fn free_ports(udp: usize, tcp: usize) -> (Vec<u16>, Vec<u16>) {
    let udp: Vec<UdpSocket> = (0..udp)
        .map(|_| UdpSocket::bind("127.0.0.1:0").unwrap())
        .collect();
    let tcp: Vec<TcpListener> = (0..tcp)
        .map(|_| TcpListener::bind("127.0.0.1:0").unwrap())
        .collect();
    (
        udp.iter().map(|s| s.local_addr().unwrap().port()).collect(),
        tcp.iter().map(|s| s.local_addr().unwrap().port()).collect(),
    )
}

fn args(list: &[&str]) -> Vec<String> {
    list.iter().map(|a| a.to_string()).collect()
}

fn api(port: u16) -> String {
    format!("http://127.0.0.1:{port}")
}

fn certified(port: u16) -> Option<u64> {
    HttpLedger::new(&api(port)).status().ok()?["certified_pulse"].as_u64()
}

fn usd(port: u16, name: &str) -> Amount {
    let ledger = HttpLedger::new(&api(port));
    let mut session = Session::open(&ledger).unwrap();
    session.balance(name, AssetId::usd()).unwrap()
}

fn handshakes_failed(port: u16) -> u64 {
    HttpLedger::new(&api(port))
        .status()
        .map(|s| {
            s["network"]["endpoint"]["handshakes_failed"]
                .as_u64()
                .unwrap_or(0)
        })
        .unwrap_or(0)
}

/// The first line of `text` that starts with `prefix`, without it.
fn line_after<'a>(text: &'a str, prefix: &str) -> &'a str {
    text.lines()
        .find_map(|line| line.strip_prefix(prefix))
        .unwrap_or_else(|| panic!("no line starting {prefix:?} in:\n{text}"))
        .trim()
}

#[test]
fn four_node_processes_and_a_gateway_certify_order_and_execute_transfers() {
    let started = Instant::now();
    let mut net = Network::new("four");
    let (quic, http) = free_ports(4, 5);
    let base = net.dir.clone();
    let dir = |name: &str| base.join(name).display().to_string();

    // Keys: each validator its own, and two gateways the peer file lists
    // (one runs; the other only probes).
    for (i, port) in quic.iter().enumerate() {
        net.sion(&args(&[
            "keys",
            "validator",
            "--dir",
            &dir(&format!("v{i}")),
            "--chain",
            "sion-test-localnet",
            "--address",
            &format!("127.0.0.1:{port}"),
            "--operator",
            &format!("operator-{i}"),
        ]));
    }
    for name in ["gateway", "prober"] {
        net.sion(&args(&[
            "keys",
            "gateway",
            "--dir",
            &dir(name),
            "--name",
            name,
        ]));
    }
    let mut genesis_args = args(&[
        "genesis",
        "--out",
        &dir(""),
        "--accounts",
        "alice,bob,carol",
    ]);
    for i in 0..4 {
        genesis_args.push("--validator".into());
        genesis_args.push(format!("{}/validator.json", dir(&format!("v{i}"))));
    }
    for name in ["gateway", "prober"] {
        genesis_args.push("--gateway".into());
        genesis_args.push(format!("{}/gateway.json", dir(name)));
    }
    let printed = net.sion(&genesis_args);
    let chain = line_after(&printed, "chain identity (pin it: sion verify --chain …):").to_string();
    let genesis = NetworkGenesis::read(&net.path("genesis.json")).unwrap();
    assert_eq!(genesis.chain_spec().unwrap().id().to_hex(), chain);

    // Four validators, each its own process, and a gateway following
    // validator 0.
    let genesis_file = dir("genesis.json");
    for (i, port) in http[..4].iter().enumerate() {
        net.spawn(
            &format!("v{i}"),
            &args(&[
                "node",
                "--dir",
                &dir(&format!("v{i}")),
                "--genesis",
                &genesis_file,
                "--api",
                &format!("127.0.0.1:{port}"),
                "--report",
                "0",
            ]),
        );
    }
    net.spawn(
        "gateway",
        &args(&[
            "gateway",
            "--dir",
            &dir("gateway"),
            "--genesis",
            &genesis_file,
            "--follow",
            &api(http[0]),
            "--api",
            &format!("127.0.0.1:{}", http[4]),
            "--report",
            "0",
        ]),
    );
    net.wait_until(
        "every node has a certified Pulse",
        Duration::from_secs(60),
        || (0..4).all(|i| certified(http[i]).is_some_and(|p| p >= 2)),
    );
    let ready = started.elapsed();

    // Transfers through the gateway: certified on their lanes, ordered,
    // executed.
    let gateway = api(http[4]);
    let sent = net.sion(&args(&["--node", &gateway, "send", "alice", "bob", "5"]));
    assert!(sent.contains("Done: paid 5 USD to bob"), "{sent}");
    let sent = net.sion(&args(&["--node", &gateway, "send", "bob", "carol", "2"]));
    assert!(sent.contains("Done: paid 2 USD to carol"), "{sent}");
    let executed: u64 = line_after(&sent, "Pulse ")
        .split(':')
        .next()
        .unwrap()
        .parse()
        .unwrap();
    let transfers = started.elapsed();

    // Every node executed the same Pulses into the same state.
    net.wait_until(
        "every node has executed the second transfer",
        Duration::from_secs(60),
        || {
            (0..4).all(|i| {
                HttpLedger::new(&api(http[i]))
                    .pulse()
                    .is_ok_and(|p| p >= Pulse(executed))
            })
        },
    );
    let headers: Vec<_> = (0..4)
        .map(|i| {
            HttpLedger::new(&api(http[i]))
                .pulse_view(Some(Pulse(executed)))
                .unwrap()
                .header
        })
        .collect();
    assert!(headers.windows(2).all(|w| w[0] == w[1]), "{headers:?}");
    let balances: Vec<[Amount; 3]> = http[..4]
        .iter()
        .map(|&port| [usd(port, "alice"), usd(port, "bob"), usd(port, "carol")])
        .collect();
    assert!(balances.windows(2).all(|w| w[0] == w[1]), "nodes disagree");
    let [alice, bob, carol] = balances[0];
    let demo = genesis.demo_usd;
    assert_eq!(carol, Amount::units(demo + 2));
    // Alice and bob each paid a fee.
    assert!(alice < Amount::units(demo - 5) && alice > Amount::units(demo - 6));
    assert!(bob < Amount::units(demo + 3) && bob > Amount::units(demo + 2));

    // A light client pinning the chain identity checks a certified Pulse
    // (served by another node than the gateway follows).
    let verified = net.sion(&args(&[
        "--node",
        &api(http[2]),
        "verify",
        "--chain",
        &chain,
        "--no-world",
    ]));
    assert!(
        verified.contains("matches the pinned identity"),
        "{verified}"
    );
    assert!(
        verified.contains("ML-DSA-44 + SLH-DSA-SHA2-128f ✓"),
        "{verified}"
    );

    // Who gets in: a key the peer file lists, with post-quantum key
    // exchange. Not a key nobody pinned, and not classical key exchange.
    let chain_id = genesis.chain_spec().unwrap().id();
    let prober = load_network_key(&net.path("prober")).unwrap();
    let listed: NodeEntry = read_json(&net.path("prober").join("gateway.json")).unwrap();
    assert_eq!(&listed.network_key, prober.public());
    let stranger = NetworkKey::from_seed(&[7; 32]);
    let before = handshakes_failed(http[1]);
    for (i, validator) in genesis.validators.iter().enumerate() {
        // As the record says: the validator's key, at its address.
        let peer: Peer = validator.entry.record.peer().unwrap();
        assert_eq!(
            peer.addresses,
            vec![SocketAddr::from(([127, 0, 0, 1], quic[i]))]
        );
        probe(
            chain_id,
            prober.public().node_id(),
            &prober,
            &peer,
            KeyExchange::PostQuantum,
        )
        .unwrap_or_else(|e| net.fail(&format!("the listed prober was refused by v{i}: {e}")));
        assert!(
            probe(
                chain_id,
                stranger.public().node_id(),
                &stranger,
                &peer,
                KeyExchange::PostQuantum
            )
            .is_err(),
            "v{i} let in a key nobody pinned"
        );
        assert!(
            probe(
                chain_id,
                prober.public().node_id(),
                &prober,
                &peer,
                KeyExchange::ClassicalOnly
            )
            .is_err(),
            "v{i} accepted classical key exchange"
        );
    }
    net.wait_until(
        "v1 counts the refused handshakes",
        Duration::from_secs(10),
        || handshakes_failed(http[1]) >= before + 2,
    );

    // One validator stops; the three others still certify (3 of 4 is a
    // quorum). The stopped one will not start again in the session it
    // signed in: that needs the consensus signing log, which is not built.
    net.kill("v1");
    let now = certified(http[0]).unwrap();
    net.wait_until(
        "three validators certify without the fourth",
        Duration::from_secs(60),
        || certified(http[0]).is_some_and(|p| p >= now + 3),
    );
    let restart = net.run(&args(&[
        "node",
        "--dir",
        &dir("v1"),
        "--genesis",
        &genesis_file,
        "--api",
        &format!("127.0.0.1:{}", http[1]),
    ]));
    let stderr = String::from_utf8_lossy(&restart.stderr);
    assert!(!restart.status.success(), "the restart was not refused");
    assert!(
        stderr.contains("already signed in consensus session 0"),
        "{stderr}"
    );

    println!(
        "network ready after {:.1} s, two transfers executed after {:.1} s, done after {:.1} s",
        ready.as_secs_f64(),
        transfers.as_secs_f64(),
        started.elapsed().as_secs_f64()
    );
}

/// The genesis refuses a validator entry that was tampered with, and a
/// node refuses to start with a network key its record does not pin.
#[test]
fn a_network_refuses_tampered_entries_and_foreign_keys() {
    let net = Network::new("refusals");
    let (quic, _) = free_ports(2, 0);
    let dir = |name: &str| net.path(name).display().to_string();
    for (i, port) in quic.iter().enumerate() {
        net.sion(&args(&[
            "keys",
            "validator",
            "--dir",
            &dir(&format!("v{i}")),
            "--address",
            &format!("127.0.0.1:{port}"),
            "--operator",
            "operator",
        ]));
    }
    // Keys are generated once.
    let again = net.run(&args(&[
        "keys",
        "validator",
        "--dir",
        &dir("v0"),
        "--address",
        "127.0.0.1:1",
        "--operator",
        "operator",
    ]));
    assert!(!again.status.success());

    // An entry whose address was changed after signing.
    let entry = Path::new(&dir("v1")).join("validator.json");
    let text = std::fs::read_to_string(&entry).unwrap();
    let moved = text.replace(&format!("127.0.0.1:{}", quic[1]), "10.9.9.9:1");
    std::fs::write(net.path("moved.json"), moved).unwrap();
    let refused = net.run(&args(&[
        "genesis",
        "--out",
        &dir("bad"),
        "--validator",
        &format!("{}/validator.json", dir("v0")),
        "--validator",
        &dir("moved.json"),
    ]));
    assert!(!refused.status.success(), "a tampered entry was accepted");

    net.sion(&args(&[
        "genesis",
        "--out",
        &dir(""),
        "--validator",
        &format!("{}/validator.json", dir("v0")),
        "--validator",
        &format!("{}/validator.json", dir("v1")),
    ]));
    // v0's directory with v1's network key.
    std::fs::copy(
        net.path("v1").join(NETWORK_KEY_FILE),
        net.path("v0").join(NETWORK_KEY_FILE),
    )
    .unwrap();
    let started = net.run(&args(&[
        "node",
        "--dir",
        &dir("v0"),
        "--genesis",
        &dir("genesis.json"),
        "--api",
        "127.0.0.1:0",
    ]));
    assert!(!started.status.success());
    assert!(
        String::from_utf8_lossy(&started.stderr)
            .contains("network key is not the one its record pins"),
        "{}",
        String::from_utf8_lossy(&started.stderr)
    );
}
